Get Product Configuration for an Account > OpenAPI definition #/components/schemas/CbuaeProduct

{
  "type": "object",
  "description": "A descriptor for an product.\nThis is a composite object that may be expanded in the future to support\nadditional account types for new API standards and product types.\n",
  "required": [
    "AccountId"
  ],
  "properties": {
    "AccountId": {
      "description": "A unique and immutable identifier produced by the financial institution to identify the account resource.",
      "type": "string"
    },
    "ShariaStructure": {
      "description": "Provides the Islamic finance contract or structure type applied to a product when it has been confirmed as Sharia-compliant.",
      "type": "string",
      "enum": [
        "Ijara",
        "ServiceIjara",
        "Murabaha",
        "Musharaka",
        "Tawarruq"
      ]
    },
    "Charges": {
      "$ref": "#/components/schemas/AEProductCharges"
    },
    "FinanceRates": {
      "anyOf": [
        {
          "$ref": "#/components/schemas/AEProductFinanceRates"
        },
        {
          "$ref": "#/components/schemas/AEJwe"
        }
      ]
    },
    "ShariaFinanceRates": {
      "description": "Finance rates for Sharia-compliant products. Can be provide in cleartext or as a JWE based on preference of LFI for sharing this information.",
      "anyOf": [
        {
          "description": "List of one-or-more finance rates for Sharia-compliant products",
          "type": "array",
          "minItems": 1,
          "items": {
            "$ref": "#/components/schemas/AEProductShariaFinanceRate1Types"
          }
        },
        {
          "$ref": "#/components/schemas/AEJwe"
        }
      ]
    },
    "DepositRates": {
      "$ref": "#/components/schemas/AEProductDepositRates"
    },
    "ExpectedProfitRates": {
      "description": "List of one-or-more deposit rates for Sharia-compliant products",
      "type": "array",
      "minItems": 1,
      "items": {
        "$ref": "#/components/schemas/AEProductExpectedProfitRate1Properties"
      }
    },
    "IsSecured": {
      "type": "boolean",
      "description": "Indicates if the product is secured by collateral."
    },
    "IsSalaryTransferRequired": {
      "description": "Indicates whether salary transfer is required as part of the product eligibility or approval conditions. Common for salary-assigned lending products."
    },
    "Tenor": {
      "description": "Product tenor",
      "type": "object",
      "minProperties": 1,
      "properties": {
        "OriginalTenor": {
          "description": "Original product tenor",
          "allOf": [
            {
              "$ref": "#/components/schemas/AEDuration"
            }
          ]
        },
        "RemainingTenor": {
          "description": "Original product tenor",
          "allOf": [
            {
              "$ref": "#/components/schemas/AEDuration"
            }
          ]
        }
      }
    },
    "AssetBacked": {
      "$ref": "#/components/schemas/AEProductAssetBackedProducts"
    },
    "RewardsBenefits": {
      "$ref": "#/components/schemas/AEProductRewardsBenefitsProperties"
    },
    "TakafulRequired": {
      "description": "Indicates whether Takaful coverage is required for the product.",
      "type": "boolean"
    },
    "TakafulDescription": {
      "description": "Provides information on the type and purpose of the required Takaful coverage.",
      "type": "string",
      "minLength": 1,
      "maxLength": 500
    }
  }
}

